const restoreItem = `-- name: RestoreItem :exec
INSERT INTO project_items (id, number, title, notes, repo, completed, completed_at, archived, created_at, updated_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(id) DO UPDATE SET
    number = excluded.number,
    title = excluded.title,
    notes = excluded.notes,
    repo = excluded.repo,
    completed = excluded.completed,
    completed_at = excluded.completed_at,
    archived = excluded.archived,
    updated_at = excluded.updated_at
`

type RestoreItemParams struct {
	ID          string
	Number      sql.NullInt64
	Title       string
	Notes       sql.NullString
	Repo        sql.NullString
	Completed   int64
	CompletedAt sql.NullString
	Archived    int64
	CreatedAt   string
	UpdatedAt   string
}

func (q *Queries) RestoreItem(ctx context.Context, arg RestoreItemParams) error {
	_, err := q.db.ExecContext(ctx, restoreItem,
		arg.ID,
		arg.Number,
		arg.Title,
		arg.Notes,
		arg.Repo,
		arg.Completed,
		arg.CompletedAt,
		arg.Archived,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	return err
}

const restoreMembership = `-- name: RestoreMembership :exec
INSERT OR IGNORE INTO project_item_memberships (item_id, project_id, position)
VALUES (?, ?, ?)
`

type RestoreMembershipParams struct {
	ItemID    string
	ProjectID string
	Position  int64
}

// Undo of a delete puts back rows that may already be there, and OR IGNORE leaves
// those alone. It does not cover a foreign key: a counterpart gone since fails
// the insert.
func (q *Queries) RestoreMembership(ctx context.Context, arg RestoreMembershipParams) error {
	_, err := q.db.ExecContext(ctx, restoreMembership, arg.ItemID, arg.ProjectID, arg.Position)
	return err
}

const restoreProject = `-- name: RestoreProject :exec

INSERT INTO projects (id, name, description, kind, status, status_reason, closed_at, position, created_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(id) DO UPDATE SET
    name = excluded.name,
    description = excluded.description,
    kind = excluded.kind,
    status = excluded.status,
    status_reason = excluded.status_reason,
    closed_at = excluded.closed_at,
    position = excluded.position
`

